mapper.sql:
where 1 = 1

    and bank_user_name = #{req.bankUserName}


    and op_name = #{req.opName}


    and recharge_user_name = #{req.rechargeUserName}


    and bank_name = #{req.bankName}


    and recharge_order_no = #{req.id}


    and status = #{req.status}


    and recharge_money  >=  #{req.priceMin}
    and recharge_money  <=  #{req.priceMax}


    and member_id = #{req.searchValue}


    and update_time  >=  #{req.selectStartDate} and update_time  <=  #{req.selectEndDate}

 and update_time  >=  '${req.downLoadDate[0]}'
 and update_time  <=  '${req.downLoadDate[1]}'

mapper.select:
SELECT bank_user_name as bankUserName, bank_name as bankName, bank_account as bankAccount, recharge_money as rechargeMoney, COUNT(1) as time, update_time as updateTime FROM member_recharge_bank WHERE `STATUS` = '3'
and recharge_money >= #{req.priceMin} and recharge_money <= #{req.priceMax}
and bank_user_name = #{req.bankUserName}
and update_time like '${req.updateTime}%'
GROUP BY bank_user_name,bank_name,recharge_money,bank_account ORDER BY bank_user_name,recharge_money

SELECT *,
sum(recharge_money) as rechargeMoney,
count(*) as totalcount
FROM member_recharge_bank
WHERE  STATUS = '3'

    and recharge_money  >=  #{req.priceMin}
    and recharge_money  <=  #{req.priceMax}


    and bank_user_name = #{req.bankUserName}


    and update_time like '${req.updateTime}%'
